package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.ModalidadeCartao; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.util.UUID;
@Entity @Table(name="pagamento_cartao") public class PagamentoCartaoEntity { @Id @Column(name="pagamento_id") public UUID pagamentoId; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="modalidade_cartao") public ModalidadeCartao modalidade; @Column(nullable=false) public short parcelas; @Column(length=30) public String bandeira; @Column(length=80) public String nsu; @Column(name="codigo_autorizacao",length=80) public String codigoAutorizacao; @Column(name="terminal_id",length=80) public String terminalId; @Column(length=80) public String gateway; @Column(name="gateway_transacao_id",length=150) public String gatewayTransacaoId; @Column(name="status_gateway",length=50) public String statusGateway; public PagamentoCartaoEntity() {} }
